  1	/**
  2	 * @file touch.c
  3	 * @brief Driver cảm ứng điện dung FT6206 / FT6336G qua I2C1 (PB8=SCL, PB9=SDA)
  4	 */
  5	#include "touch.h"
  6	#include "stm32f469xx.h"
  7	
  8	#define TS_ADDR_1 0x70  /* 7-bit 0x38 << 1 (FT6336G / FT6206 chuẩn) */
  9	#define TS_ADDR_2 0x54  /* 7-bit 0x2A << 1 (Một số biến thể FT6206) */
 10	
 11	static uint8_t g_ts_addr = TS_ADDR_1;
 12	
 13	static inline void i2c_delay(void)
 14	{
 15	    for (volatile int i = 0; i < 150; i++) {
 16	        __asm__ volatile("nop");
 17	    }
 18	}
 19	
 20	static inline void scl_high(void)
 21	{
 22	    GPIOB->BSRR = (1UL << 8);
 23	}
 24	
 25	static inline void scl_low(void)
 26	{
 27	    GPIOB->BSRR = (1UL << (8 + 16));
 28	}
 29	
 30	static inline void sda_high(void)
 31	{
 32	    GPIOB->BSRR = (1UL << 9);
 33	}
 34	
 35	static inline void sda_low(void)
 36	{
 37	    GPIOB->BSRR = (1UL << (9 + 16));
 38	}
 39	
 40	static inline uint8_t sda_read(void)
 41	{
 42	    return (GPIOB->IDR & (1UL << 9)) ? 1 : 0;
 43	}
 44	
 45	static void i2c_start(void)
 46	{
 47	    sda_high();
 48	    scl_high();
 49	    i2c_delay();
 50	    sda_low();
 51	    i2c_delay();
 52	    scl_low();
 53	    i2c_delay();
 54	}
 55	
 56	static void i2c_stop(void)
 57	{
 58	    sda_low();
 59	    i2c_delay();
 60	    scl_high();
 61	    i2c_delay();
 62	    sda_high();
 63	    i2c_delay();
 64	}
 65	
 66	static uint8_t i2c_write_byte(uint8_t byte)
 67	{
 68	    for (int i = 0; i < 8; i++) {
 69	        if (byte & 0x80) {
 70	            sda_high();
 71	        } else {
 72	            sda_low();
 73	        }
 74	        byte <<= 1;
 75	        i2c_delay();
 76	        scl_high();
 77	        i2c_delay();
 78	        scl_low();
 79	    }
 80	    
 81	    /* Đọc ACK */
 82	    sda_high();
 83	    i2c_delay();
 84	    scl_high();
 85	    i2c_delay();
 86	    uint8_t ack = sda_read();
 87	    scl_low();
 88	    i2c_delay();
 89	    
 90	    return ack; /* 0 = ACK, 1 = NACK */
 91	}
 92	
 93	static uint8_t i2c_read_byte(uint8_t send_ack)
 94	{
 95	    uint8_t byte = 0;
 96	    sda_high();
 97	    for (int i = 0; i < 8; i++) {
 98	        byte <<= 1;
 99	        scl_high();
100	        i2c_delay();
101	        if (sda_read()) {
102	            byte |= 0x01;
103	        }
104	        scl_low();
105	        i2c_delay();
106	    }
107	    
108	    /* Gửi ACK hoặc NACK */
109	    if (send_ack) {
110	        sda_low();
111	    } else {
112	        sda_high();
113	    }
114	    i2c_delay();
115	    scl_high();
116	    i2c_delay();
117	    scl_low();
118	    sda_high();
119	    i2c_delay();
120

121	    return byte;
122	}
123	
124	static int i2c_read_regs(uint8_t dev_addr, uint8_t reg, uint8_t *buf, uint16_t len)
125	{
126	    i2c_start();
127	    if (i2c_write_byte(dev_addr & 0xFE) != 0) {
128	        i2c_stop();
129	        return -1;
130	    }
131	    if (i2c_write_byte(reg) != 0) {
132	        i2c_stop();
133	        return -1;
134	    }
135	    
136	    i2c_start();
137	    if (i2c_write_byte(dev_addr | 0x01) != 0) {
138	        i2c_stop();
139	        return -1;
140	    }
141	    
142	    for (uint16_t i = 0; i < len; i++) {
143	        buf[i] = i2c_read_byte(i < (len - 1));
144	    }
145	    i2c_stop();
146	    return 0;
147	}
148	
149	int Touch_Init(void)
150	{
151	    /* Bật clock GPIOB */
152	    RCC->AHB1ENR |= RCC_AHB1ENR_GPIOBEN;
153	    
154	    /* Cấu hình PB8 (SCL) và PB9 (SDA): Output Open-Drain, Pull-up, High Speed */
155	    /* PB8: MODER bits 17:16 = 01 */
156	    /* PB9: MODER bits 19:18 = 01 */
157	    GPIOB->MODER &= ~((3UL << (8 * 2)) | (3UL << (9 * 2)));
158	    GPIOB->MODER |=  ((1UL << (8 * 2)) | (1UL << (9 * 2)));
159	    
160	    /* Open-drain: OTYPER bit 8 = 1, bit 9 = 1 */
161	    GPIOB->OTYPER |= (1UL << 8) | (1UL << 9);
162	    
163	    /* Pull-up: PUPDR bits 17:16 = 01, bits 19:18 = 01 */
164	    GPIOB->PUPDR &= ~((3UL << (8 * 2)) | (3UL << (9 * 2)));
165	    GPIOB->PUPDR |=  ((1UL << (8 * 2)) | (1UL << (9 * 2)));
166	    
167	    /* Very High speed: OSPEEDR bits 17:16 = 11, bits 19:18 = 11 */
168	    GPIOB->OSPEEDR |= ((3UL << (8 * 2)) | (3UL << (9 * 2)));
169	    
170	    /* 9 xung unlock bus I2C */
171	    sda_high();
172	    for (int i = 0; i < 9; i++) {
173	        scl_low();
174	        i2c_delay();
175	        scl_high();
176	        i2c_delay();
177	    }
178	    i2c_stop();
179	    
180	    /* Quét địa chỉ IC cảm ứng */
181	    i2c_start();
182	    if (i2c_write_byte(TS_ADDR_1) == 0) {
183	        g_ts_addr = TS_ADDR_1;
184	        i2c_stop();
185	        return 0;
186	    }
187	    i2c_stop();
188	    
189	    i2c_start();
190	    if (i2c_write_byte(TS_ADDR_2) == 0) {
191	        g_ts_addr = TS_ADDR_2;
192	        i2c_stop();
193	        return 0;
194	    }
195	    i2c_stop();
196	    
197	    /* Mặc định dùng TS_ADDR_1 */
198	    g_ts_addr = TS_ADDR_1;
199	    return 0;
200	}
201	
202	int Touch_Read(uint16_t *x, uint16_t *y)
203	{
204	    uint8_t data[5];
205	    /* Đọc 5 byte từ thanh ghi 0x02 (TD_STATUS) đến 0x06 */
206	    if (i2c_read_regs(g_ts_addr, 0x02, data, 5) != 0) {
207	        return 0;
208	    }
209	    
210	    uint8_t touches = data[0] & 0x0F;
211	    if (touches == 0 || touches > 2) {
212	        return 0;
213	    }
214	    
215	    uint16_t raw_x = ((uint16_t)(data[1] & 0x0F) << 8) | data[2];
216	    uint16_t raw_y = ((uint16_t)(data[3] & 0x0F) << 8) | data[4];
217	    
218	    /* Trên màn hình STM32F469I-DISCO OTM8009A ở chế độ Landscape (800x480):
219	     * raw_y là trục dài (0..799)
220	     * raw_x là trục ngắn (0..479)
221	     */
222	    if (x != 0) {
223	        *x = raw_y;
224	    }
225	    if (y != 0) {
226	        *y = raw_x;
227	    }
228	    return 1;
229	}

