 22	    uint32_t *fb = (uint32_t *)LCD_FB_START_ADDRESS;
 23	
 24	    for (uint32_t r = 0; r < LOGO_PTIT_HEIGHT; r++) {
 25	        for (uint32_t c = 0; c < LOGO_PTIT_WIDTH; c++) {
 26	            uint32_t color = logo_ptit_data[r * LOGO_PTIT_WIDTH + c];
