162	int UI_HandleTouch(uint16_t x, uint16_t y)
163	{
164	    /* Kiem tra cham trong vung nut bam.
165	     * Nut bam dat tai BTN_X = 240..560.
166	     * Theo truc Y: BTN_Y = 400..450 (hoac 30..80 neu toa do Y bi lat).
167	     */
168	    int in_x = (x >= 200 && x <= 600);
169	    int in_y = ((y >= 360 && y <= 470) || (y >= 10 && y <= 110));
170	
171	    if (in_x && in_y) {
172	        UI_ToggleScreen();
173	        return 1;
174	    }
175	    return 0;
176	}

100	
101	    /* Bật clock AHB1 cho GPIOA, GPIOD, GPIOG, GPIOK */
102	    RCC->AHB1ENR |= RCC_AHB1ENR_GPIOAEN | RCC_AHB1ENR_GPIODEN | RCC_AHB1ENR_GPIOGEN | RCC_AHB1ENR_GPIOKEN;
103	
104	    /* Cấu hình PA0 (Nút WAKEUP): Chế độ Input (00), Pull-down (10) */
105	    GPIOA->MODER &= ~(3UL << (BUTTON_PIN * 2));
106	    GPIOA->PUPDR &= ~(3UL << (BUTTON_PIN * 2));
107	    GPIOA->PUPDR |= (2UL << (BUTTON_PIN * 2));
108	
109	    /* Cấu hình PG6 (LED1): Chế độ Output (01), tắt ban đầu (LED tích cực mức thấp) */
110	    GPIOG->MODER &= ~(3UL << (LED1_PIN * 2));
111	    GPIOG->MODER |= (1UL << (LED1_PIN * 2));
112	    GPIOG->BSRR = (1UL << LED1_PIN);
113	
114	    /* Cấu hình PD4 (LED2) & PD5 (LED3): Chế độ Output (01), tắt ban đầu */
115	    GPIOD->MODER &= ~((3UL << (LED2_PIN * 2)) | (3UL << (LED3_PIN * 2)));
116	    GPIOD->MODER |= ((1UL << (LED2_PIN * 2)) | (1UL << (LED3_PIN * 2)));
117	    GPIOD->BSRR = (1UL << LED2_PIN) | (1UL << LED3_PIN);
118	
119	    /* Cấu hình PK3 (LED4): Chế độ Output (01), tắt ban đầu */
120	    GPIOK->MODER &= ~(3UL << (LED4_PIN * 2));
121	    GPIOK->MODER |= (1UL << (LED4_PIN * 2));
122	    GPIOK->BSRR = (1UL << LED4_PIN);
123	}
